package com.bank.autocomplete.service;

import com.bank.autocomplete.dto.AutocompleteResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;

@Service
@Slf4j
public class AutocompleteService {

    private final List<String> symbols = List.of(
        "RELIANCE", "TCS", "HDFC", "INFY", "WIPRO", "BSE", "BAJAJ", "SBI",
        "ICICI", "AXIS", "ITC", "HCL", "ADANI", "TATASTEEL", "BHARTIARTL"
    );

    public AutocompleteResult sortByLength(String prefix) {

        // ═══ Ascending by length ═══
        List<String> asc = symbols.stream()
            .sorted(Comparator.comparingInt(String::length))
            .toList();
        log.info("Ascending: {}", asc);

        // ═══ Descending by length ═══
        List<String> desc = symbols.stream()
            .sorted(Comparator.comparingInt(String::length).reversed())
            .toList();
        log.info("Descending: {}", desc);

        // ═══ Ascending with alphabetical tiebreak ═══
        List<String> withTiebreak = symbols.stream()
            .sorted(Comparator.comparingInt(String::length)
                .thenComparing(Comparator.naturalOrder()))
            .toList();
        log.info("With tiebreak: {}", withTiebreak);

        // ═══ Filtered by prefix, sorted by length ═══
        List<String> matching = symbols.stream()
            .filter(s -> s.startsWith(prefix.toUpperCase()))
            .sorted(Comparator.comparingInt(String::length)
                .thenComparing(Comparator.naturalOrder()))
            .toList();
        log.info("Matching '{}': {}", prefix, matching);

        return new AutocompleteResult(asc, desc, withTiebreak, matching);
    }
}
