package com.bank.autocomplete.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class SortByLengthTest {

    @Test
    void sortAscendingByLength() {
        List<String> sorted = List.of("RELIANCE", "TCS", "HDFC", "INFY").stream()
            .sorted(Comparator.comparingInt(String::length))
            .toList();
        assertThat(sorted).containsExactly("TCS", "HDFC", "INFY", "RELIANCE");
    }

    @Test
    void sortDescendingByLength() {
        List<String> sorted = List.of("RELIANCE", "TCS", "HDFC").stream()
            .sorted(Comparator.comparingInt(String::length).reversed())
            .toList();
        assertThat(sorted).containsExactly("RELIANCE", "HDFC", "TCS");
    }

    @Test
    void tiebreakByAlphabeticalForSameLength() {
        List<String> sorted = List.of("INFY", "HDFC", "AXIS", "WIPRO", "TCS").stream()
            .sorted(Comparator.comparingInt(String::length)
                .thenComparing(Comparator.naturalOrder()))
            .toList();
        assertThat(sorted).containsExactly("TCS", "AXIS", "HDFC", "INFY", "WIPRO");
        // length 3: TCS. length 4: AXIS, HDFC, INFY (alphabetical). length 5: WIPRO.
    }

    @Test
    void emptyAndSingleElement() {
        assertThat(List.<String>of().stream()
            .sorted(Comparator.comparingInt(String::length)).toList()).isEmpty();
        assertThat(List.of("TCS").stream()
            .sorted(Comparator.comparingInt(String::length)).toList()).containsExactly("TCS");
    }
}
